type Severity = 'Critical' | 'High' | 'Medium' | 'Low';
type Status = 'Pending' | 'Analyzing' | 'Assigned' | 'In Progress' | 'Resolved';
type Section = 'Command Center' | 'Live India Map' | 'Emergency Reports' | 'AI Rescue Agent' | 'Rescue Teams' | 'Relief Resources' | 'Analytics' | 'AI Assistant' | 'Settings';

type Analysis = {
  mode: 'OPENROUTER' | 'GEMINI' | 'DEMO MODE'; severity: Severity; priority: number; reasoning: string; peopleAtRisk: number;
  resources: string[]; actions: string[]; teamType: string; medicalUrgency: string; responseUrgency: string; nextAction: string;
};
type Incident = {
  id: string; title: string; state?: string; city: string; district: string; location: string; lat: number; lng: number;
  severity: Severity; status: Status; waterLevel: number; affected: number; trapped: number;
  vulnerable: string; medical: string; description: string; priority: number; time: string; teamId?: string; analysis?: Analysis;
};
type Team = { id: string; name: string; state?: string; district?: string; city: string; lat: number; lng: number; status: 'Available' | 'Assigned' | 'Standby'; equipment: string[]; response: string; incidentId?: string };
type Resource = { id: string; name: string; amount: number; unit: string; threshold: number; icon: string; state?: string; district?: string; city?: string };
type Log = { id: string; action: string; detail: string; time: string; status: 'Completed' | 'Pending' };
type AppState = { incidents: Incident[]; teams: Team[]; resources: Resource[]; logs: Log[] };

