const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string | undefined;
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined;
const supabase = supabaseUrl && supabaseKey ? createClient(supabaseUrl, supabaseKey) : null;
const aiEndpoint = supabaseUrl ? `${supabaseUrl}/functions/v1/rescue-ai` : null;

async function callRescueAi(payload: Record<string, unknown>) {
  if (!aiEndpoint) throw new Error('AI service is not connected yet');
  const response = await fetch(aiEndpoint, { method: 'POST', headers: { 'Content-Type': 'application/json', ...(supabaseKey ? { Authorization: `Bearer ${supabaseKey}`, apikey: supabaseKey } : {}) }, body: JSON.stringify(payload) });
  const result: unknown = await response.json();
  if (!response.ok || !result || typeof result !== 'object' || !('answer' in result || 'severity' in result)) throw new Error('AI service returned an invalid response');
  return result as Record<string, unknown>;
}

function fallbackAnalysis(incident: Pick<Incident, 'trapped' | 'affected' | 'waterLevel' | 'medical'>): Analysis {
  const priority = Math.min(100, Math.max(20, 40 + incident.trapped * 2 + Math.min(25, incident.affected / 10) + incident.waterLevel * 8));
  const severity: Severity = priority >= 80 || incident.trapped >= 10 ? 'Critical' : priority >= 60 ? 'High' : priority >= 40 ? 'Medium' : 'Low';
  return { mode: 'DEMO MODE', severity, priority: Math.round(priority), reasoning: `Demo assessment uses ${incident.trapped} trapped people, ${incident.affected} affected people, and ${incident.waterLevel}m reported water. Missing details remain flagged for human verification.`, peopleAtRisk: Math.max(incident.trapped, Math.round(incident.affected * .35)), resources: ['Rescue boat', 'Life jackets', incident.trapped > 0 ? 'Medical kit' : 'Drinking water'], actions: ['Verify location and water depth', 'Contact the closest available response team', 'Keep a human controller in the approval loop'], teamType: incident.trapped > 0 ? 'Boat rescue team with medical support' : 'Flood assessment and relief team', medicalUrgency: incident.medical, responseUrgency: severity === 'Critical' ? 'Immediate' : severity === 'High' ? 'Within 30 minutes' : 'Within 2 hours', nextAction: incident.trapped > 0 ? 'Review for immediate boat extraction' : 'Request a field verification update' };
}

